new_block = '''def _lapply(node, delta):
    """Add ``delta`` to the lag of every resident of the subtree."""
    if node is None:
        return None
    return _lmk(node.key, node.prio, node.pkt, node.bank, node.left, node.right,
                node.val + delta, node.lazy + delta)


def _lpush(node):
    """Materialise the pending increment of a subtree into its children."""
    delta = node.lazy
    if not delta:
        return node
    return _lmk(node.key, node.prio, node.pkt, node.bank,
                _lapply(node.left, delta), _lapply(node.right, delta),
                node.val, 0)


def live_size(root):
    return _size(root)


def live_insert(root, key, pkt, bank, prio):
    """Insert a resident.

    The pending increments of the visited nodes are materialised before the
    descent, therefore a freshly admitted resident starts with a lag of exactly
    zero even when its neighbours already suffered overtakes.
    """
    if root is None:
        return LiveNode(key, prio, pkt, bank, None, None, 1, 0, 0)
    if root.lazy:
        root = _lpush(root)
    if key < root.key:
        left = live_insert(root.left, key, pkt, bank, prio)
        if left.prio > root.prio:
            middle = left.right
            newright = _lmk(root.key, root.prio, root.pkt, root.bank, middle,
                            root.right, root.val, root.lazy)
            return _lmk(left.key, left.prio, left.pkt, left.bank, left.left,
                        newright, left.val, left.lazy)
        return _lmk(root.key, root.prio, root.pkt, root.bank, left, root.right,
                    root.val, root.lazy)
    right = live_insert(root.right, key, pkt, bank, prio)
    if right.prio > root.prio:
        middle = right.left
        newleft = _lmk(root.key, root.prio, root.pkt, root.bank, root.left,
                       middle, root.val, root.lazy)
        return _lmk(right.key, right.prio, right.pkt, right.bank, newleft,
                    right.right, right.val, right.lazy)
    return _lmk(root.key, root.prio, root.pkt, root.bank, root.left, right,
                root.val, root.lazy)


def live_merge(left, right):
    """Concatenate two subtrees whose keys are strictly ordered."""
    if left is None:
        return right
    if right is None:
        return left
    if left.prio > right.prio:
        if left.lazy:
            left = _lpush(left)
        return _lmk(left.key, left.prio, left.pkt, left.bank, left.left,
                    live_merge(left.right, right), left.val, left.lazy)
    if right.lazy:
        right = _lpush(right)
    return _lmk(right.key, right.prio, right.pkt, right.bank,
                live_merge(left, right.left), right.right, right.val, right.lazy)


def live_delete(root, key, acc=0):
    """Remove a resident.

    Returns ``(new_root, removed_node_or_None, lag_of_removed_node)``.
    """
    if root is None:
        return None, None, 0
    if key < root.key:
        newleft, node, lag = live_delete(root.left, key, acc + root.lazy)
        if node is None:
            return root, None, 0
        return (_lmk(root.key, root.prio, root.pkt, root.bank, newleft,
                     root.right, root.val, root.lazy), node, lag)
    if key > root.key:
        newright, node, lag = live_delete(root.right, key, acc + root.lazy)
        if node is None:
            return root, None, 0
        return (_lmk(root.key, root.prio, root.pkt, root.bank, root.left,
                     newright, root.val, root.lazy), node, lag)
    lag = root.val + acc
    if root.lazy:
        left = _lapply(root.left, root.lazy)
        right = _lapply(root.right, root.lazy)
    else:
        left = root.left
        right = root.right
    return live_merge(left, right), root, lag


def live_find(root, key):
    """Locate a resident: ``(node_or_None, lag)``."""
    acc = 0
    while root is not None:
        if key == root.key:
            return root, root.val + acc
        acc += root.lazy
        root = root.left if key < root.key else root.right
    return None, 0


'''
